<template><div class="admin-applications-page"><DemoIdentitySwitcher />
<div v-if="loading" class="applications-queue applications-state"><span class="applications-spinner"></span><strong>Loading review</strong></div><div v-else-if="!application" class="applications-queue applications-state"><strong>Application not found</strong></div><div v-else-if="!canReview" class="applications-queue applications-state"><strong>Review access unavailable</strong><p>Claim a review slot before opening this form.</p><RouterLink :to="detailRoute">Return to application</RouterLink></div>
<template v-else><header class="review-page-header"><RouterLink class="application-back-link" :to="detailRoute">← Application detail</RouterLink><span class="demo-data-badge">{{ slot.reviewLabel }}</span><h1>{{ application.applicantName }}</h1><p>{{ application.pathwayLabel }} · {{ application.reference }} · Reviewing as {{ identity.name }}</p><strong>{{ locked ? `Submitted ${formatDate(slot.submittedAt)}` : 'In-memory draft · refreshing resets unsubmitted work' }}</strong></header>
<nav class="review-stage-progress" aria-label="Review stages"><span v-for="(label,index) in stageLabels" :key="label" :class="{ active: stage === index + 1, complete: stage > index + 1 || locked }">{{ index + 1 }}. {{ label }}</span></nav>
<section v-if="stage === 1 && !locked" class="review-stage-card"><h2>Reviewer confirmation and conflict check</h2><div class="impartiality-guidance"><h3>Assess evidence, suitability, conduct, commitment and potential</h3><p>Do not score based on:</p><ul><li v-for="item in inclusionGuidance" :key="item">{{ item }}</li></ul></div><label v-for="item in confirmationsConfig" :key="item.id" class="review-confirmation"><input v-model="confirmations[item.id]" type="checkbox"> {{ item.label }}</label><p v-if="showErrors && !confirmationsComplete" class="criterion-error">Complete every confirmation before beginning.</p><div class="stage-actions"><button type="button" class="danger-muted" @click="declareConflict">Declare a conflict and release review</button><button type="button" @click="beginReview">Confirm and begin review</button></div></section>
<section v-else-if="stage === 2 && !locked" class="review-stage-card"><h2>Eligibility and verification checks</h2><p>These checks do not add or subtract percentage points. Clarification and failures require a private explanation.</p><article v-for="check in eligibilityConfig" :key="check.id" class="eligibility-check"><h3>{{ check.label }}</h3><div><label v-for="option in eligibilityOptions" :key="option.value"><input v-model="eligibility[check.id]" type="radio" :name="`eligibility-${check.id}`" :value="option.value"> {{ option.label }}</label></div><label v-if="['clarification','does-not-meet'].includes(eligibility[check.id])">Internal explanation (required)<textarea v-model="eligibilityExplanations[check.id]" rows="2"></textarea></label><p v-if="showErrors && eligibilityIssue(check.id)" class="criterion-error">Select a result and explain any clarification or unmet requirement.</p></article><div class="stage-actions"><button type="button" @click="stage=1">Back</button><button type="button" @click="continueEligibility">Continue to scoring</button></div></section>
<div v-else-if="stage === 3 && !locked" class="review-page-grid"><main><SubmittedAnswers :answers="application.answers" /></main><aside><form class="review-form" @submit.prevent="continueScoring"><h2>Creator Programme scoring</h2><p class="panel-note">Score only supplied evidence. Internal calculations and outcome thresholds are intentionally hidden.</p><section v-for="criterion in criteria" :key="criterion.id" class="criterion-card"><h2>{{ criterion.order }}. {{ criterion.label }}</h2><p>{{ criterion.description }}</p><strong class="reviewer-question">{{ criterion.reviewerQuestion }}</strong><fieldset :aria-describedby="`error-${criterion.id}`"><legend>Score: <strong>{{ scores[criterion.id] || 'Not selected' }}</strong> / 10</legend><div class="score-options"><label v-for="score in 10" :key="score"><input v-model.number="scores[criterion.id]" type="radio" :name="criterion.id" :value="score" @change="saveDraft"><span>{{ score }}</span></label></div></fieldset><div class="score-anchor-list"><span v-for="anchor in criterion.scoreAnchors" :key="anchor.range"><strong>{{ anchor.range }}</strong> {{ anchor.label }}</span></div><div class="criterion-examples"><span v-for="score in [3,5,7,9]" :key="score"><strong>{{ score }}:</strong> {{ criterion.examples[score] }}</span></div><label class="criterion-comment">Explain your score (recommended)<textarea v-model="comments[criterion.id]" rows="3" @input="saveDraft"></textarea></label><p v-if="showErrors && !scores[criterion.id]" :id="`error-${criterion.id}`" class="criterion-error">Select a score from 1 to 10.</p></section><div class="stage-actions"><button type="button" @click="stage=2">Back</button><button type="submit">Continue to assessment</button></div></form></aside></div>
<section v-else-if="stage === 4 && !locked" class="review-stage-card"><h2>Clarification, concerns and overall assessment</h2><div v-if="clarificationItems.length" class="clarification-summary"><h3>Eligibility items requiring attention</h3><article v-for="item in clarificationItems" :key="item.id"><strong>{{ item.label }}</strong><p>{{ eligibilityExplanations[item.id] }}</p></article></div><div class="serious-concern"><h3>Serious concern</h3><p>Use clarification for a missing link, unclear answer or minor inconsistency. Serious concerns include unsafe, discriminatory, exploitative or materially false conduct.</p><label><input v-model="seriousConcern" type="radio" :value="false"> No serious concerns</label><label><input v-model="seriousConcern" type="radio" :value="true"> Flag for admin attention</label><label v-if="seriousConcern">Private explanation (required)<textarea v-model="concernExplanation" rows="3"></textarea></label><p v-if="showErrors && seriousConcern && !concernExplanation.trim()" class="criterion-error">Explain the serious concern.</p></div><label class="overall-assessment">Overall assessment (optional)<span>Summarise strongest qualities, areas requiring attention and anything an admin should consider.</span><textarea v-model="overallAssessment" rows="5"></textarea></label><section class="review-submit-panel"><h3>Submission summary</h3><p>Reviewer confirmation completed: {{ confirmationsComplete ? 'Yes' : 'No' }}</p><p>Eligibility checks: {{ eligibilitySummary }}</p><ul><li v-for="criterion in criteria" :key="criterion.id">{{ criterion.label }}: {{ scores[criterion.id] || 'Missing' }}/10</li></ul><p>{{ emptyCommentCount }} score explanations are empty. Comments are encouraged but optional.</p><p>Serious concern: {{ seriousConcern ? 'Flagged' : 'None' }}</p><p>Submission locks confirmations, checks, explanations, scores, comments and assessment.</p><div class="stage-actions"><button type="button" @click="stage=3">Back</button><button type="button" @click="prepareSubmit">Review and submit</button></div></section></section>
<section v-if="confirming && !locked" class="review-confirm" role="dialog" aria-modal="true"><h2>Submit this immutable review?</h2><p>No weights, percentage or outcome prediction is shown in reviewer context.</p><button type="button" @click="confirming=false">Continue editing</button><button ref="confirmButton" type="button" @click="submit">Confirm final submission</button></section>
<section v-if="locked" class="review-complete"><h2>Review submitted</h2><p>{{ slot.reviewLabel }} is locked. Thank you for completing the assessment.</p><p v-if="slot.seriousConcern">A serious concern was privately flagged for Admin attention.</p><RouterLink :to="detailRoute">Return to application</RouterLink></section></template></div></template>
<script>import { nextTick } from 'vue'; import DemoIdentitySwitcher from './components/DemoIdentitySwitcher.vue'; import SubmittedAnswers from './components/SubmittedAnswers.vue'; import { CREATOR_PROGRAMME_CRITERIA, ELIGIBILITY_CHECKS, REVIEWER_CONFIRMATIONS, canAccessReview, declareReviewConflict, getAdminApplication, getCurrentReviewSlot, getDemoIdentity, missingCriteria, saveReviewDraft, startReview, submitReview, validateEligibility } from './applicationAdminData.js'; import { ELIGIBILITY_OPTIONS, INCLUSION_GUIDANCE } from './fixtures/creatorProgrammeReviewRubric.js';
export default { name: 'AdminApplicationReview', components: { DemoIdentitySwitcher, SubmittedAnswers }, props: { applicationId: { type: String, required: true } }, data: () => ({ application: null, loading: true, stage: 1, stageLabels: ['Confirmation','Eligibility','Scoring','Overall assessment'], criteria: CREATOR_PROGRAMME_CRITERIA, confirmationsConfig: REVIEWER_CONFIRMATIONS, eligibilityConfig: ELIGIBILITY_CHECKS, eligibilityOptions: ELIGIBILITY_OPTIONS, inclusionGuidance: INCLUSION_GUIDANCE, confirmations: {}, eligibility: {}, eligibilityExplanations: {}, scores: {}, comments: {}, seriousConcern: false, concernExplanation: '', overallAssessment: '', showErrors: false, confirming: false }), computed: { canReview() { return canAccessReview(); }, identity() { return getDemoIdentity(); }, slot() { return getCurrentReviewSlot(); }, locked() { return this.slot?.state === 'submitted'; }, detailRoute() { return { name: 'AdminApplicationDetail', params: { applicationId: this.applicationId } }; }, confirmationsComplete() { return this.confirmationsConfig.every((item) => this.confirmations[item.id] === true); }, eligibilityResult() { return validateEligibility(this.eligibility, this.eligibilityExplanations); }, clarificationItems() { return this.eligibilityResult.blocking; }, missing() { return missingCriteria(this.scores); }, emptyCommentCount() { return this.criteria.filter((criterion) => !String(this.comments[criterion.id] || '').trim()).length; }, eligibilitySummary() { return `${this.eligibilityConfig.length - this.clarificationItems.length} meet · ${this.clarificationItems.length} require Admin attention`; } }, async mounted() { this.application = await getAdminApplication(this.applicationId); this.loading = false; if (this.application && this.canReview) { const slot = startReview(); Object.assign(this, { confirmations: { ...slot.confirmations }, eligibility: { ...slot.eligibility }, eligibilityExplanations: { ...slot.eligibilityExplanations }, scores: { ...slot.scores }, comments: { ...slot.comments }, seriousConcern: slot.seriousConcern, concernExplanation: slot.concernExplanation, overallAssessment: slot.overallAssessment || '', stage: slot.state === 'submitted' ? 4 : Object.keys(slot.scores).length ? 3 : 1 }); } }, methods: { draftData() { return { confirmations: { ...this.confirmations }, eligibility: { ...this.eligibility }, eligibilityExplanations: { ...this.eligibilityExplanations }, overallAssessment: this.overallAssessment }; }, saveDraft() { if (!this.locked) saveReviewDraft(this.scores, this.comments, this.draftData()); }, beginReview() { this.showErrors = true; if (!this.confirmationsComplete) return; this.showErrors = false; this.saveDraft(); this.stage = 2; }, declareConflict() { const explanation = window.prompt('Short internal conflict explanation (required):'); if (explanation?.trim()) { declareReviewConflict(explanation); this.$router.push(this.detailRoute); } }, eligibilityIssue(id) { return !this.eligibility[id] || (['clarification','does-not-meet'].includes(this.eligibility[id]) && !String(this.eligibilityExplanations[id] || '').trim()); }, continueEligibility() { this.showErrors = true; if (this.eligibilityResult.missing.length || this.eligibilityResult.unexplained.length) return; this.showErrors = false; this.saveDraft(); this.stage = 3; }, continueScoring() { this.showErrors = true; if (this.missing.length) return; this.showErrors = false; this.saveDraft(); this.stage = 4; }, async prepareSubmit() { this.showErrors = true; if (this.missing.length || !this.confirmationsComplete || this.eligibilityResult.missing.length || this.eligibilityResult.unexplained.length || (this.seriousConcern && !this.concernExplanation.trim())) return; this.confirming = true; await nextTick(); this.$refs.confirmButton?.focus(); }, submit() { submitReview(this.scores, this.comments, { flagged: this.seriousConcern, explanation: this.concernExplanation }, this.draftData()); this.confirming = false; }, formatDate(value) { return new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)); } } };</script><style src="./AdminApplications.css"></style>
